create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.TMS_TOUR (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH',
	SYSTEM_ID NUMBER(38,0) NOT NULL COMMENT 'Spezifiziert das Quellsystem, aus dem die Daten kommen.',
	TMS_TOUR_ID NUMBER(38,0) NOT NULL COMMENT 'ID des Tours (Tournummer). Eine Tour kann an mehr als einem Datum stattfinden, daher ist die Spalte tms_tour_id allein nicht eindeutig. Aus pltop.tonr',
	DAT_TOUR DATE NOT NULL COMMENT 'Tourdatum',
	TMS_TOUR_LFD_NR NUMBER(38,0) NOT NULL COMMENT 'SKey für die Tabelle tms_tour im Quellsystem. Aus pltop.top_id',
	TRANSPORTATION_UNIT_ID_EXT VARCHAR(20) COMMENT 'Externe TU-Nummer',
	TMS_TOURART_ID VARCHAR(2) NOT NULL COMMENT 'die Art der Tour, z. B. ob es sich um eine direkte Lieferung zwischen Kunden oder um eine Lieferung zwischen Lager und Kunde/Lager handelt. ''0'' = Kunde-Kunde, ''1'' = Lager-Kunde, ''2'' = Kunde-Lager, ''3'' = Lager-Lager',
	TMS_TOURTYP_ID NUMBER(38,0) COMMENT 'Die Spalte \""tourtyp\"" dient der detaillierten Kategorisierung von Touren für Reporting und Abrechnung. Je nach Tourart können verschiedene Tourtypen vorkommmen. (105 = \""01 - Zutour - keine Abrechnung\"", 106 = \""03 - Internationaler Transport\"", 201 = \""02 - Abholung Lieferant\"", ...)',
	TMS_TOURSTATUS_ID NUMBER(38,0) COMMENT 'Tourstatus (Verladen, Abgerechnet,…)',
	TMS_TOUR_BEZ VARCHAR(30) COMMENT 'Name der Tour',
	ANZ_STOPP NUMBER(38,0) COMMENT 'Anzahl der Stopps(Geschäftspartner) auf der Tour',
	ANZ_STELLPLATZ NUMBER(38,0) COMMENT 'Anzahl Stellplätze pro Tour',
	TMS_FAHRZEUG_ID VARCHAR(20) COMMENT 'Fahrzeugnummer',
	TMS_FAHRZEUGTYP_ID NUMBER(38,0) COMMENT 'Fahrzeugtyp',
	TMS_TRAILER_ID VARCHAR(20) COMMENT 'Hängernummer',
	TMS_TRAILER_TYP_ID NUMBER(38,0) COMMENT 'Hängertyp',
	SPEDITION_TMS_GP_ID VARCHAR(30) COMMENT 'ID des tms_gp, welcher hier als Spedition auftrifft',
	SPEDITION_TMS_GP_TYP_CD VARCHAR(3) COMMENT 'Code für den tms_gp-Typ, welcher hier als Spedition auftrifft',
	TEMPERATURGRUPPE_ID VARCHAR(20) COMMENT 'UK (ungekühlt) / TK (tiefgekühlt) / TE (temperiert) / GK (gekühlt) -> wird nur für Kühlinformation genutzt',
	GUTSCHRIFT_ERSTELLT_FG NUMBER(38,0) COMMENT 'Kennzeichen, ob eine Gutschrift erstellt wurde',
	STARTLAGER_TMS_GP_ID VARCHAR(30) COMMENT 'ID des tms_gp, welcher hier als Startlager auftrifft',
	STARTLAGER_TMS_GP_TYP_CD VARCHAR(3) COMMENT 'Code für den tms_gp-Typ, welcher hier als Startlager auftrifft',
	ZIELLAGER_TMS_GP_ID VARCHAR(30) COMMENT 'ID des tms_gp, welcher hier als Ziellager auftrifft',
	ZIELLAGER_TMS_GP_TYP_CD VARCHAR(3) COMMENT 'Code für den tms_gp-Typ, welcher hier als Ziellager auftrifft',
	MAUT_KM NUMBER(38,0) COMMENT 'Mautstrecke in Metern (deutsche Autobahnmaut)',
	LEER_KM NUMBER(38,0) COMMENT 'Anzahl der Leerfahrten, die von einem Spediteur durchgeführt wurden. Leerfahrten können aus verschiedenen Gründen notwendig werden, z. B. wenn der Markt an einem abgelegenen Ort liegt oder wenn keine Rückladung für eine beladene Fahrt gefunden werden kann.',
	ANZ_AENDERUNG NUMBER(38,0) COMMENT 'Anzahl manuellen Änderungen der Tour nach der Optimierung',
	BETRAG_FIXKOSTEN NUMBER(18,2) COMMENT 'Speditionsfixkosten, Rechnung fehlt dann???',
	TMS_TOUR_DISPOSTELLE_ID NUMBER(38,0) COMMENT 'Dispostelle des Tours',
	TMS_TOURART_DETAIL_ID NUMBER(38,0) COMMENT 'Genauere Unterteilung als die tms_tourart_id (Kunde-Lager, Lager-Lager,...), die direkt von Wanko kommt. Die Spalte wird im ETL-Prozess über die Tourpositionen angereichert.\n            1 = Filialbelieferung\n            2 = Shuttle (zwischen VZ)\n            3 = Hofverkehr\n            4 =I ndustrieabholung\n            5 = Manuelle Tour\n            6 = Fleischwerktour\n            7 = Fleischwerk Shuttle',
	TMS_TOUR_RICHTUNGSART_ID NUMBER(38,0) COMMENT 'Gibt an, ob es sich bei der Tour um einen Rundlauf oder eine einfache Fahrt handelt. Die Information wird im ETL-Prozess aus den Tourpositionen ermittelt. \n            1 = OneWay\n            2 = Rundlauf\n            3 = Industrieabholung\n            4 = Sonstige',
	SORTIMENT_TEMPERATURGRUPPE_ID NUMBER(38,0) COMMENT 'Temperaturgruppe aus den Sortimenten, der mit der Tour verknüpften Aufträge. Die Information wird im ETL-Prozess ermittelt. Inhalt besagt, ob die Tour mit einem Kühlfahrzeug durchgeführt werden muss.\n            0 = Nicht gesetzt\n            1 = TK (Tiefgekühlt)\n            2 = GK (Gekühlt)\n            3 = TE (Temperiert)\n            4 = UK (Ungekühlt)\n            5 = TB (Thermobehälter)',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TMS_TOUR_STRATEGISCH_ID NUMBER(38,0) COMMENT 'Strategische Tournummer (wird beim Ableiten aus dem Feld tms_tour_id der strategischen Tour gefüllt).',
	ANTRIEBSART_ID NUMBER(38,0) COMMENT 'ID für die generelle Antriebstechnologie des Fahrzeugs auf dieser Tour. Antriebsart: 1 = Diesel, 2 = Elektro, 3 = Gas, 4 = Wasserstoff, 0 = nicht zugeordnet.\n            Diese Spalte ist nicht identisch mit der Treibstoffart (tms_treibstoff). Bspw. Ein LKW kann mit HVO100 (Pflanzenöl) oder fossilim Diesel betankt werden (= unterschiedliche Treibstoffe), die Antriebsart bleibt in beiden Fällen 1 (Diesel), da die Motorentechnologie identisch ist.',
	constraint PK_TMS_TOUR primary key (MANDANT_ID, SYSTEM_ID, TMS_TOUR_ID, DAT_TOUR)
)COMMENT='TMS - Die Tabelle enthält die Informationen über Touren im System, einschließlich Tourtyp, Start- und Zielort und Fahrzeuge. Aus der Quelle pltop (WANKO)'
;
